insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-151","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The integer $n$ that converts an empirical formula into the molecular formula is calculated as","options":["empirical mass / molecular mass","molecular mass / empirical formula mass","atomic number / mass number","percentage of carbon / 12"],"answer_index":1,"explanation":"$n = M / E$, then each empirical subscript is multiplied by $n$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-152","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"For an ionic solid such as $\\mathrm{Na_2CO_3}$, the formula written on the bottle is already","options":["a molecular formula that can be halved","the empirical formula of the compound","only a percentage composition","an unbalanced equation"],"answer_index":1,"explanation":"Ionic compounds are represented by the simplest ratio of ions, which is the empirical formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-153","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A hydrocarbon analyses as 80% carbon and 20% hydrogen by mass. Its empirical formula is","options":["$\\mathrm{CH}$","$\\mathrm{CH_2}$","$\\mathrm{CH_3}$","$\\mathrm{C_2H_5}$"],"answer_index":2,"explanation":"Mole ratio C : H $= (80/12) : (20/1) = 6.67 : 20 = 1 : 3$, so $\\mathrm{CH_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-154","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A compound contains 40.0% C, 6.7% H and 53.3% O. The empirical formula matching these percentages is","options":["$\\mathrm{CHO}$","$\\mathrm{CH_2O}$","$\\mathrm{C_2H_2O}$","$\\mathrm{C_2H_6O}$"],"answer_index":1,"explanation":"Moles C : H : O $= 3.33 : 6.7 : 3.33 = 1 : 2 : 1$, which is $\\mathrm{CH_2O}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-155","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A vapour has empirical formula CH and a vapour density corresponding to $M = 78$ g mol$^{-1}$. The molecular formula of the vapour is","options":["$\\mathrm{C_2H_2}$","$\\mathrm{C_3H_3}$","$\\mathrm{C_6H_6}$","$\\mathrm{C_{12}H_{12}}$"],"answer_index":2,"explanation":"Empirical mass 13; $n = 78/13 = 6$, giving $\\mathrm{C_6H_6}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-156","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An iron oxide is 70% Fe and 30% O by mass (Fe = 56, O = 16). The oxide’s empirical formula is","options":["$\\mathrm{FeO}$","$\\mathrm{Fe_2O_3}$","$\\mathrm{Fe_3O_4}$","$\\mathrm{FeO_2}$"],"answer_index":1,"explanation":"Moles Fe : O $= (70/56) : (30/16) = 1.25 : 1.875 = 2 : 3$, so $\\mathrm{Fe_2O_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-157","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A hydrocarbon is 85.7% carbon, the rest hydrogen. The empirical formula of that hydrocarbon is","options":["$\\mathrm{CH}$","$\\mathrm{CH_2}$","$\\mathrm{CH_3}$","$\\mathrm{C_2H_2}$"],"answer_index":1,"explanation":"C : H moles $= (85.7/12) : (14.3/1) \\approx 7.14 : 14.3 = 1 : 2$, hence $\\mathrm{CH_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-158","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A chloro-compound is 24.24% C, 4.04% H and 71.72% Cl. Its molar mass is 99 g mol$^{-1}$. The molecular formula is","options":["$\\mathrm{CH_2Cl}$","$\\mathrm{C_2H_4Cl_2}$","$\\mathrm{C_2H_3Cl}$","$\\mathrm{C_3H_6Cl_2}$"],"answer_index":1,"explanation":"Empirical moles give $\\mathrm{CH_2Cl}$ (E = 49.5); $n = 99/49.5 = 2$, so $\\mathrm{C_2H_4Cl_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-159","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In the Haber equation $\\mathrm{N_2} + 3\\mathrm{H_2} \\rightarrow 2\\mathrm{NH_3}$, each mole of nitrogen that reacts consumes hydrogen amounting to","options":["1 mol","2 mol","3 mol","6 mol"],"answer_index":2,"explanation":"The coefficient of $\\mathrm{H_2}$ is 3, so the mole ratio N$_2$ : H$_2$ is 1 : 3.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-160","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"According to $2\\mathrm{H_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{H_2O}$, complete use of 1 mol of oxygen produces water equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"One mole of $\\mathrm{O_2}$ corresponds to two moles of $\\mathrm{H_2O}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-161","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Thermal decomposition $\\mathrm{CaCO_3} \\rightarrow \\mathrm{CaO} + \\mathrm{CO_2}$ is 1 : 1 : 1 in moles. From 1 mol of limestone the carbon dioxide obtained is","options":["0.5 mol","1 mol","2 mol","3 mol"],"answer_index":1,"explanation":"Each mole of $\\mathrm{CaCO_3}$ yields one mole of $\\mathrm{CO_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-162","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The laboratory oxygen preparation $2\\mathrm{KClO_3} \\rightarrow 2\\mathrm{KCl} + 3\\mathrm{O_2}$ gives, from 2 mol of chlorate, oxygen amounting to","options":["2 mol","3 mol","4 mol","6 mol"],"answer_index":1,"explanation":"The O$_2$ coefficient is 3 when 2 mol of $\\mathrm{KClO_3}$ decompose.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-163","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Complete combustion $\\mathrm{C} + \\mathrm{O_2} \\rightarrow \\mathrm{CO_2}$ links carbon and carbon dioxide in the mole ratio","options":["1 : 1","1 : 2","2 : 1","1 : 4"],"answer_index":0,"explanation":"Coefficients of C and $\\mathrm{CO_2}$ are both 1.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-164","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Magnesium burns as $2\\mathrm{Mg} + \\mathrm{O_2} \\rightarrow 2\\mathrm{MgO}$. Oxygen amounting to 1 mol therefore requires magnesium equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"Two moles of Mg are needed for each mole of $\\mathrm{O_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-165","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Methane burns as $\\mathrm{CH_4} + 2\\mathrm{O_2} \\rightarrow \\mathrm{CO_2} + 2\\mathrm{H_2O}$. The oxygen-to-methane mole ratio demanded by the equation is","options":["1 : 1","2 : 1","1 : 2","4 : 1"],"answer_index":1,"explanation":"Two moles of $\\mathrm{O_2}$ are required for every mole of $\\mathrm{CH_4}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-166","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Contact-process oxidation $2\\mathrm{SO_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{SO_3}$ converts 1 mol of oxygen into sulphur trioxide amounting to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"One mole of $\\mathrm{O_2}$ produces two moles of $\\mathrm{SO_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-167","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Aluminium burns in oxygen: $4\\mathrm{Al} + 3\\mathrm{O_2} \\rightarrow 2\\mathrm{Al_2O_3}$. Four moles of aluminium therefore form alumina equal to","options":["1 mol","2 mol","3 mol","4 mol"],"answer_index":1,"explanation":"The product coefficient is 2 when 4 mol of Al react.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-168","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen chloride is formed by $\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$. One mole of hydrogen gas yields HCl equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"The HCl coefficient is 2 for each mole of $\\mathrm{H_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-169","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Propane burns as $\\mathrm{C_3H_8} + 5\\mathrm{O_2} \\rightarrow 3\\mathrm{CO_2} + 4\\mathrm{H_2O}$. Complete combustion of 2 mol of propane releases carbon dioxide amounting to","options":["2 mol","3 mol","6 mol","8 mol"],"answer_index":2,"explanation":"Each mole of $\\mathrm{C_3H_8}$ gives 3 mol $\\mathrm{CO_2}$, so 2 mol give 6 mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-170","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A Haber converter is charged with 10 mol of hydrogen and surplus nitrogen. The maximum ammonia that can form is","options":["6.67 mol","10 mol","15 mol","20 mol"],"answer_index":0,"explanation":"From $3\\mathrm{H_2} \\rightarrow 2\\mathrm{NH_3}$, 10 mol H$_2$ produce $(10 \\times 2)/3 = 20/3 \\approx 6.67$ mol NH$_3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-171","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of $\\mathrm{KClO_3}$ are fully decomposed to KCl and O$_2$. The STP volume of oxygen collected is","options":["22.4 L","44.8 L","67.2 L","89.6 L"],"answer_index":2,"explanation":"2 mol chlorate give 3 mol O$_2$; $3 \\times 22.4 = 67.2$ L at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-172","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A bunsen flame consumes 16 g of methane completely (M = 16 g mol$^{-1}$). The STP volume of $\\mathrm{CO_2}$ produced is","options":["11.2 L","16.0 L","22.4 L","44.8 L"],"answer_index":2,"explanation":"16 g is 1 mol $\\mathrm{CH_4}$ and gives 1 mol $\\mathrm{CO_2}$, which occupies 22.4 L at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-173","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 50 g charge of $\\mathrm{CaCO_3}$ (M = 100 g mol$^{-1}$) is heated until decomposition is complete. The lime $\\mathrm{CaO}$ (M = 56 g mol$^{-1}$) obtained weighs","options":["28 g","50 g","56 g","44 g"],"answer_index":0,"explanation":"0.50 mol of carbonate yields 0.50 mol of CaO, i.e. 28 g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-174","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Ethane burns as $2\\mathrm{C_2H_6} + 7\\mathrm{O_2} \\rightarrow 4\\mathrm{CO_2} + 6\\mathrm{H_2O}$. A 15 g sample of ethane (M = 30) is burnt in 64 g of oxygen. The mass of $\\mathrm{CO_2}$ formed and the unused $\\mathrm{O_2}$ are","options":["44 g and 8 g","22 g and 16 g","88 g and 0 g","44 g and 0 g"],"answer_index":0,"explanation":"0.50 mol ethane needs 1.75 mol (56 g) O$_2$ and makes 1.0 mol (44 g) CO$_2$; 64 − 56 = 8 g O$_2$ remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-175","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"After a reaction stops, the starting material that is left unused is called the","options":["limiting reagent","excess reagent","catalyst","theoretical product"],"answer_index":1,"explanation":"The excess reagent remains because the other reactant ran out first.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
    answer_index int,
    explanation text,
    images jsonb,
    source jsonb,
    difficulty text,
    concept_id text,
    appear_count int,
    years jsonb,
    exams jsonb,
    verified boolean
  )
on conflict (question_id) do update set
  appear_count = excluded.appear_count,
  years = excluded.years,
  exams = excluded.exams,
  verified = excluded.verified;